class Solution:
    def maxValue(self, nums: List[int], k: int) -> int:
        from itertools import combinations
        best = 0
        for c in combinations(range(len(nums)), 2 * k):
            a = b = 0
            for i in c[:k]: a |= nums[i]
            for i in c[k:]: b |= nums[i]
            best = max(best, a ^ b)
        return best

