class Solution {
public:
    int k, best = 0; vector<int> nums; vector<int> cur;
    void go(int i, int taken) {
        if (taken == 2 * k) {
            int a = 0, b = 0;
            for (int t = 0; t < k; t++) a |= nums[cur[t]];
            for (int t = k; t < 2 * k; t++) b |= nums[cur[t]];
            best = max(best, a ^ b); return;
        }
        if (i >= (int)nums.size() || (int)nums.size() - i < 2 * k - taken) return;
        cur.push_back(i); go(i + 1, taken + 1); cur.pop_back(); go(i + 1, taken);
    }
    int maxValue(vector<int>& ns, int kk) { nums = ns; k = kk; go(0, 0); return best; }
};

