class Solution:
    def maxValue(self, nums: List[int], k: int) -> int:
        n = len(nums)
        def build(a):
            P = [[0] * (k + 1) for _ in range(len(a) + 1)]
            for i, x in enumerate(a):
                for c in range(1, k + 1):
                    P[i + 1][c] = max(P[i][c], P[i][c - 1] | x)
            return P
        P = build(nums)
        S = build(nums[::-1])
        return max(P[i][k] ^ S[n - i][k] for i in range(k, n - k + 1))

