class Solution {
public:
    int maxValue(vector<int>& nums, int k) {
        int n = nums.size();
        auto build = [&](vector<int> a) {
            vector<vector<int>> P(n + 1, vector<int>(k + 1, 0));
            for (int i = 0; i < n; i++)
                for (int c = 1; c <= k; c++)
                    P[i + 1][c] = max(P[i][c], P[i][c - 1] | a[i]);
            return P;
        };
        vector<int> ra(nums.rbegin(), nums.rend());
        auto P = build(nums), Q = build(ra);
        int ans = 0;
        for (int i = k; i + k <= n; i++) ans = max(ans, P[i][k] ^ Q[n - i][k]);
        return ans;
    }
};

