class Solution {
    private int[][] build(int[] a, int k) {
        int[][] P = new int[a.length + 1][k + 1];
        for (int i = 0; i < a.length; i++)
            for (int c = 1; c <= k; c++)
                P[i + 1][c] = Math.max(P[i][c], P[i][c - 1] | a[i]);
        return P;
    }
    public int maxValue(int[] nums, int k) {
        int n = nums.length;
        int[] ra = new int[n];
        for (int i = 0; i < n; i++) ra[n - 1 - i] = nums[i];
        int[][] P = build(nums, k), Q = build(ra, k);
        int ans = 0;
        for (int i = k; i + k <= n; i++) ans = Math.max(ans, P[i][k] ^ Q[n - i][k]);
        return ans;
    }
}

